import { test, expect } from "@playwright/test";

// Base URL for API requests - customize as needed
const API_BASE = process.env.API_BASE_URL || "http://localhost:3000";

test.describe("Baseline API Tests - Health & Status", () => {
  test("server is running", async ({ request }) => {
    // Basic connectivity check
    const response = await request.get(`${API_BASE}/`);
    expect(response.status()).toBeLessThan(500);
  });

  test("health endpoint responds", async ({ request }) => {
    // Customize: Change to your actual health endpoint
    const response = await request.get(`${API_BASE}/api/health`);

    if (response.status() === 404) {
      console.log("No /api/health endpoint - consider adding one");
      test.skip();
    }

    expect(response.ok()).toBeTruthy();
    const body = await response.json();
    expect(body).toHaveProperty("status");
  });
});

