test.describe("Baseline API Tests - Error Handling", () => {
  test("invalid JSON returns 400, not 500", async ({ request }) => {
    // Find an endpoint that accepts POST
    const response = await request.post(`${API_BASE}/api/health`, {
      headers: { "Content-Type": "application/json" },
      data: "this is not valid json{{{",
    });

    // Should handle gracefully
    expect(response.status()).toBeLessThan(500);
  });

  test("unknown endpoints return 404", async ({ request }) => {
    const response = await request.get(`${API_BASE}/api/this-does-not-exist-12345`);
    expect(response.status()).toBe(404);
  });
});

